import type { Locale } from './locales';

// UI strings and props descriptions of every locale, from the translation
// memory (generated by scripts/i18n/generate.ts, adr/0033)
const messages = import.meta.glob<Record<string, string>>('../generated/i18n/*.json', {
  import: 'default',
  eager: true,
});

function table(locale: Locale) {
  return messages[`../generated/i18n/${locale}.json`];
}

/**
 * Marks a UI string to translate where it is defined (e.g. docs-nav.ts).
 * Literal strings in `t(locale, '...')` and `msg('...')` are collected by scripts/i18n/ui.ts.
 */
export const msg = (text: string) => text;

/**
 * The translation of an English UI string, or the string itself. `{name}`
 * placeholders are kept. Takes the locale (from `useLocale()`) instead of being
 * a hook-made closure: Qwik serializes what JSX expressions capture, and a
 * locale string can be serialized but a function cannot.
 */
export function t(locale: Locale, text: string): string {
  return table(locale)?.[text] ?? text;
}
